INSERT INTO Wireframe VALUES('cmrsi4oz4001brwjuzkc6p8s5','cmrby3y0000001znnofoo0a53','관리자 로그인','html',unistr('<!doctype html><html><head><meta charset="utf-8"><style>\u000a:root{--bg:#f4f4f5;--surface:#fff;--line:#d4d4d8;--ink:#3f3f46;--muted:#a1a1aa;--fill:#e4e4e7;}\u000a*{box-sizing:border-box;margin:0;padding:0}\u000abody{background:var(--bg);color:var(--ink);font:13px/1.5 -apple-system,BlinkMacSystemFont,''Segoe UI'',sans-serif;display:flex;align-items:center;justify-content:center;min-height:100vh}\u000a.card{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:28px;width:320px;display:flex;flex-direction:column;gap:10px}\u000a.brand{font-weight:700;font-size:18px;text-align:center}\u000a.sub{color:var(--muted);font-size:12px;text-align:center}\u000a.gbtn{display:flex;align-items:center;justify-content:center;gap:10px;border:1px solid var(--line);border-radius:8px;padding:11px;background:var(--surface);color:var(--ink);cursor:pointer;font:inherit;font-weight:600;margin-top:12px}\u000a.gbtn .g{display:inline-flex;align-items:center;justify-content:center;width:20px;height:20px;border-radius:50%;background:var(--fill);font-weight:700;font-size:13px}\u000a.note{color:var(--muted);font-size:12px;text-align:center;min-height:16px}\u000a.err{color:#b91c1c;font-size:12px;text-align:center;min-height:14px}\u000a.hr{height:1px;background:var(--line);margin:8px 0 2px}\u000a.demo{color:var(--muted);font-size:11px;text-align:center;text-decoration:underline;cursor:pointer}\u000a</style></head>\u000a<body data-screen="admin-login">\u000a  <div class="card">\u000a    <div class="brand">추노 백오피스</div>\u000a    <div class="sub">사내 관리자 전용</div>\u000a    <button class="gbtn" onclick="document.getElementById(''e'').textContent='''';document.getElementById(''note'').textContent=''구글 계정 선택 화면으로 이동합니다…''">\u000a      <span class="g">G</span> Google로 로그인\u000a    </button>\u000a    <div class="note" id="note">사전 등록된 관리자 이메일만 로그인할 수 있어요.</div>\u000a    <div